<?php
namespace SenderSuite;

/** Source scheduled-history projection and conservative cancellation; not an automatic retry service. */
final class ScheduledSms {
    private $db;private $config;private $records;
    public function __construct(Database $db,Config $config,callable $clock=null){$this->db=$db;$this->config=$config;$this->records=new Records($db,$clock);}
    public static function definitions(){return array('/send/scheduled'=>array('GET'),'/send/scheduled/(?P<sid>-?[0-9]+)/cancel'=>array('POST'));}
    private function table($name){return Schema::identifier($this->db->schema()->table($name));}
    public static function linked(Database $db,$messageId){$rows=$db->rows('SELECT id,status,message_id,schedule_at,executed_at,error FROM '.Schema::identifier($db->schema()->table('scheduled_messages')).' WHERE message_id=%d LIMIT 2',array($messageId));$rows=array_map(function($r)use($db){return $db->decode('scheduled_messages',$r);},$rows);if(count($rows)>1){throw new AuthFailure(409,'Scheduled message linkage is ambiguous.');}return $rows?$rows[0]:null;}
    /** Called in the same transaction, message first then schedule. No network. */
    public static function sync(Database $db,Records $records,array $m,array $patch){
        if(!array_key_exists('status',$patch)&&!array_key_exists('provider_message_id',$patch)){return;}$row=self::linked($db,$m['id']);if(!$row){return;}$new=array_replace($m,$patch);$status=$new['status'];$map=array('queued'=>'pending','sending'=>$new['provider_message_id']!==null?'sent':'sending','sent'=>'sent','delivered'=>'sent','failed'=>'failed','cancelled'=>'cancelled','unknown'=>'unknown');if(!isset($map[$status])){throw new AuthFailure(409,'Unsupported scheduled delivery state.');}
        $d=array('status'=>$map[$status]);if($row['status']==='cancelled'&&$d['status']!=='cancelled'){return;}if(in_array($d['status'],array('failed','unknown'),true)){$d['error']=$d['status']==='unknown'?'Submission or delivery needs manual review; never automatically retry.':'Delivery admission or submission failed.';}elseif(in_array($d['status'],array('sent','cancelled'),true)){$d['error']=null;}
        if($row['executed_at']===null&&in_array($d['status'],array('sent','failed','unknown'),true)){$d['executed_at']=$records->now();}
        $changed=false;foreach($d as $key=>$v){if($row[$key]!==$v){$changed=true;}}if(!$changed){return;}
        if($db->update('scheduled_messages',$d,array('id'=>$row['id'],'status'=>$row['status'],'message_id'=>$row['message_id'],'schedule_at'=>$row['schedule_at'],'executed_at'=>$row['executed_at'],'error'=>$row['error']))!==1){throw new AuthFailure(409,'Scheduled message changed. Retry without resubmitting a provider request.');}
    }
    public function listing(array $q){
        $page=DataRoutes::integer($q['page']??1,'page',1,1000000);$per=DataRoutes::integer($q['per_page']??50,'per_page',1,100);$status=DataRoutes::text($q,'status',null,null,100);$search=DataRoutes::text($q,'search',null,null,1000);$where=array('1=1');$args=array();if($status!==null&&$status!==''&&$status!=='all'){$where[]='s.status=%s';$args[]=$status;}if($search!==null&&$search!==''){$where[]='(LOWER(s.phone_number) LIKE LOWER(%s) OR LOWER(s.body) LIKE LOWER(%s))';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}
        $base=' FROM '.$this->table('scheduled_messages').' s WHERE '.implode(' AND ',$where);$total=(int)$this->db->rows('SELECT COUNT(*) AS n'.$base,$args)[0]['n'];$order=' ORDER BY s.schedule_at '.($status==='pending'?'ASC':'DESC').',s.id ASC LIMIT %d OFFSET %d';$params=array_merge($args,array($per,($page-1)*$per));
        $budget=(int)$this->db->rows('SELECT COALESCE(SUM(x.bytes),0) AS n FROM (SELECT COALESCE(OCTET_LENGTH(s.body),0) AS bytes'.$base.$order.') x',$params)[0]['n'];if($budget>4194304){throw new AuthFailure(413,'Scheduled page exceeds the text limit. Reduce the page size.');}
        $picked='SELECT s.id'.$base.$order;$from=' FROM ('.$picked.') picked JOIN '.$this->table('scheduled_messages').' s ON s.id=picked.id LEFT JOIN '.$this->table('contacts').' c ON c.id=s.contact_id';
        $rows=$this->db->rows('SELECT s.id,s.contact_id,s.phone_number,s.body,s.schedule_at,s.status,CASE WHEN s.error IS NULL OR s.error=\'\' THEN s.error ELSE \'Delivery reported an error.\' END AS error,s.executed_at,s.message_id,s.list_id,s.sim_number,c.first_name,c.last_name,c.business_name'.$from.' ORDER BY s.schedule_at '.($status==='pending'?'ASC':'DESC').',s.id ASC',$params);$items=array();$bytes=0;
        foreach($rows as $r){$name=Compat::strip(($r['first_name']??'').' '.($r['last_name']??''));if($name===''){$name=$r['business_name']?:null;}$item=array('id'=>(int)$r['id'],'contact_id'=>$r['contact_id']!==null?(int)$r['contact_id']:null,'contact_name'=>$name,'phone'=>$r['phone_number'],'body'=>$r['body'],'body_preview'=>implode('',array_map(array(Compat::class,'chr'),array_slice(Compat::points($r['body']),0,100))),'schedule_at'=>Records::iso($r['schedule_at']),'status'=>$r['status'],'error'=>$r['error'],'executed_at'=>Records::iso($r['executed_at']),'message_id'=>$r['message_id']!==null?(int)$r['message_id']:null,'list_id'=>$r['list_id']!==null?(int)$r['list_id']:null,'sim_number'=>(int)$r['sim_number']);$bytes+=strlen(json_encode($item,JSON_THROW_ON_ERROR));if($bytes>8388608){throw new AuthFailure(413,'Scheduled response is too large. Reduce the page size.');}$items[]=$item;}
        return array('total'=>$total,'page'=>$page,'per_page'=>$per,'items'=>$items);
    }
    public function cancel($id,array $user){
        if(($user['role']??'')!=='admin'){throw new AuthFailure(403,'Application administrator role required.');}$rows=$this->db->rows('SELECT id,status,message_id,schedule_at FROM '.$this->table('scheduled_messages').' WHERE id=%d',array($id));if(!$rows){throw new AuthFailure(404,'Not found');}$s=$this->db->decode('scheduled_messages',$rows[0]);if($s['status']!=='pending'){throw new AuthFailure(400,'Cannot cancel a message that is '.$s['status']);}
        if($s['message_id']!==null){(new SmsOutbox($this->db,$this->config))->cancel($s['message_id'],$user);$fresh=$this->db->rows('SELECT status FROM '.$this->table('scheduled_messages').' WHERE id=%d',array($id));if(($fresh[0]['status']??null)==='cancelled'){return array('success'=>true,'status'=>'cancelled');}}
        if($this->db->update('scheduled_messages',array('status'=>'cancelled'),array('id'=>$s['id'],'status'=>'pending','message_id'=>$s['message_id'],'schedule_at'=>$s['schedule_at']))!==1){throw new AuthFailure(409,'Scheduled message changed. Reload before cancelling.');}return array('success'=>true,'status'=>'cancelled');
    }
    public static function handle($request,array $c,array $user){$s=new self($c['db'],$c['config']);$path=trim(substr($request->get_route(),strlen('/sender-suite/v1/')),'/');if($path==='send/scheduled'&&$request->get_method()==='GET'){return $s->listing($request->get_query_params());}if($request->get_method()==='POST'&&preg_match('~^send/scheduled/(-?[0-9]+)/cancel$~D',$path,$m)){return $s->cancel(DataRoutes::integer($m[1],'sid',1),$user);}throw new AuthFailure(404,'Not found');}
}
